<?php
namespace App\Controllers; use App\Middleware\Auth; use App\Services\Database; use App\Services\View; final class DashboardController { public function index(){ Auth::requireUser(); $db=Database::pdo(); $uid=Auth::user()['id']; $stats=['cvs'=>(int)$db->query("SELECT COUNT(*) FROM resumes WHERE user_id=$uid AND archived_at IS NULL")->fetchColumn(),'month'=>(int)$db->query("SELECT COUNT(*) FROM resumes WHERE user_id=$uid AND created_at>=DATE_FORMAT(NOW(),'%Y-%m-01')")->fetchColumn(),'credits'=>(int)($db->query("SELECT ai_credits FROM users WHERE id=$uid")->fetchColumn() ?: 0),'ats'=>18,'completion'=>86]; $recent=$db->query("SELECT * FROM resumes WHERE user_id=$uid ORDER BY updated_at DESC LIMIT 6")->fetchAll(); View::render('dashboard/index',['title'=>'Dashboard','stats'=>$stats,'recent'=>$recent]); }}
